const q = $input.first().json;
const parts = [];
if (q.project_type) parts.push('Tipo proyecto: ' + q.project_type);
if (q.location_zone) parts.push('Zona: ' + q.location_zone);
if (q.property_type) parts.push('Inmueble: ' + q.property_type);
if (q.area_m2) parts.push('Area: ' + q.area_m2 + ' m2');
if (q.summary) parts.push('Resumen: ' + q.summary);
if (q.briefing_summary) parts.push('Briefing: ' + q.briefing_summary);
if (q.tags && Array.isArray(q.tags)) parts.push('Tags: ' + q.tags.join(', '));
const text = parts.join('. ');
const topK = q.top_k || 5;
return [{ json: { text: text || 'reforma vivienda generica', top_k: topK, exclude_project_id: q.exclude_project_id || null } }];

const r = $input.first().json;
const built = $('Build Search Text').first().json;
if (r.status !== 'success' || !r.embedding) {
  return [{ json: { error: 'embedding_failed', error_detail: r.error_message || 'unknown', similar_cases: [] } }];
}
const vectorStr = '[' + r.embedding.join(',') + ']';
return [{ json: { vector_str: vectorStr, top_k: built.top_k, exclude_project_id: built.exclude_project_id, search_text: built.text, dimensions: r.dimensions } }];

const items = $input.all();
const format = $('Format Vector').first().json;
const cases = items.filter(i => i.json && i.json.id).map(i => ({
  id: i.json.id,
  similarity: parseFloat(i.json.similarity || 0),
  project_type: i.json.project_type,
  location_zone: i.json.location_zone,
  property_type: i.json.property_type,
  area_m2: i.json.area_m2,
  summary: i.json.summary,
  scope_summary: i.json.scope_summary,
  cost_estimated: i.json.cost_estimated,
  duration_estimated_days: i.json.duration_estimated_days,
  lessons_learned: i.json.lessons_learned,
  patterns: i.json.patterns,
  decisions_made: i.json.decisions_made,
  tags: i.json.tags
}));
return [{ json: { status: 'success', cases_found: cases.length, search_text: format.search_text, top_k: format.top_k, similar_cases: cases } }];
